var raw = JSON.parse(msg.payload);
var stream = raw.stream || '';
var data = raw.data || raw;

var symbol = (data.s || stream.split('@')[0].toUpperCase());
var price = parseFloat(data.c || data.p || 0);
var volume = parseFloat(data.v || 0);

if (!symbol || isNaN(price)) return null;

msg.payload = {
    symbol: symbol,
    price: price,
    volume: volume,
    time: new Date().toISOString()
};

return msg;

// Throttle: giới hạn cập nhật max 1 lần/giây cho mỗi cặp coin
var now = Date.now();
var key = 'last_' + msg.payload.symbol;
var last = context.get(key) || 0;

if (now - last < 1000) return null;
context.set(key, now);

// Lưu trữ payload gốc đầy đủ vào flow context để phục vụ node Log Prices
flow.set('price_' + msg.payload.symbol, msg.payload);

// Trả về nguyên vẹn msg chứa đầy đủ msg.payload.symbol, price, volume
return msg;

var d = msg.payload;
msg.topic = `INSERT INTO realtime_prices (symbol, price, volume, updated_at)
  VALUES ('${d.symbol}', ${d.price}, ${d.volume}, NOW())
  ON DUPLICATE KEY UPDATE price=${d.price}, volume=${d.volume}, updated_at=NOW()`;
return msg;

var d = msg.payload;

// Lấy chính xác tên coin, phòng hờ bị mất thì tự map theo giá
var currentSymbol = d.symbol;
if (!currentSymbol) {
    var priceCheck = parseFloat(d.price);
    if (priceCheck > 30000) currentSymbol = "BTCUSDT";
    else if (priceCheck > 1000 && priceCheck < 5000) currentSymbol = "ETHUSDT";
    else if (priceCheck > 1 && priceCheck < 200) currentSymbol = "SOLUSDT";
    else currentSymbol = "UNKNOWN";
} else {
    currentSymbol = currentSymbol.toUpperCase();
}

// ĐỊNH NGHĨA TÊN TABLE (MEASUREMENT)
msg.measurement = 'crypto_price';

// CÚ PHÁP ĐẶC BIỆT CHO NODE INFLUXDB OUT CŨ:
// Gộp cả trường số (Fields) và thẻ phân loại (Tags) vào chung payload dạng Array
msg.payload = [
    {
        price: parseFloat(d.price),
        volume: parseFloat(d.volume)
    },
    {
        symbol: currentSymbol // Đây chính là cách vứt Tag vào cho node cũ hiểu
    }
];

return msg;

var d = msg.payload;
// Phòng hờ nếu node InfluxDB chạy trước làm mất d.symbol, 
// chúng ta tự đoán nhận token dựa trên giá tiền thực tế
var symbol = d.symbol;
if (!symbol) {
  if (d.price > 30000) symbol = "BTCUSDT";
  else if (d.price > 1000 && d.price < 5000) symbol = "ETHUSDT";
  else if (d.price > 1 && d.price < 200) symbol = "SOLUSDT";
  else symbol = "UNKNOWN";
}

// Tự động đọc cấu hình từ file .env
var highThreshold = 0;
var lowThreshold = 0;

if (symbol === "BTCUSDT") {
  highThreshold = parseFloat(env.get("BTC_HIGH")) || 120000;
  lowThreshold = parseFloat(env.get("BTC_LOW")) || 100000;
} else if (symbol === "ETHUSDT") {
  highThreshold = parseFloat(env.get("ETH_HIGH")) || 7000;
  lowThreshold = parseFloat(env.get("ETH_LOW")) || 4000;
} else if (symbol === "SOLUSDT") {
  highThreshold = parseFloat(env.get("SOL_HIGH")) || 300;
  lowThreshold = parseFloat(env.get("SOL_LOW")) || 100;
}

if (highThreshold === 0 || lowThreshold === 0) return null;

// Cooldown: Chống spam alert 5 phút
var coolKey = 'cooldown_' + symbol;
var cd = context.get(coolKey) || {};
var now = Date.now();

var alertType = null;
var thresholdValue = null;

if (d.price > highThreshold) {
  if (!cd.HIGH || (now - cd.HIGH) > 300000) {
    alertType = 'HIGH';
    thresholdValue = highThreshold;
    cd.HIGH = now;
  }
} else if (d.price < lowThreshold) {
  if (!cd.LOW || (now - cd.LOW) > 300000) {
    alertType = 'LOW';
    thresholdValue = lowThreshold;
    cd.LOW = now;
  }
}

if (!alertType) return null;
context.set(coolKey, cd);

var timeStr = new Date().toISOString().replace('T', ' ').split('.')[0];
var emoji = alertType === 'HIGH' ? '🔴' : '🔵';
var alertLabel = alertType === 'HIGH' ? 'ALERT HIGH' : 'ALERT LOW';

// Chuỗi gửi Telegram viết bằng dấu nháy đơn thường để loại bỏ 100% lỗi Syntax Backtick
var text = emoji + ' *' + alertLabel + '*\n\n' +
  'Coin: `' + symbol + '`\n' +
  'Price: `' + d.price.toLocaleString() + ' USD`\n' +
  'Threshold: `' + thresholdValue.toLocaleString() + ' USD`\n' +
  'Time: `' + timeStr + '`';

msg.alert = {
  symbol: symbol,
  alert_type: alertType,
  price: d.price,
  threshold: thresholdValue,
  time: timeStr
};
msg.telegram_text = text;

return msg;

var botToken = env.get('TELEGRAM_BOT_TOKEN');
var chatId = env.get('TELEGRAM_CHAT_ID');

if (!botToken || !chatId || botToken === 'YOUR_TELEGRAM_BOT_TOKEN_HERE') {
  node.warn('Telegram not configured');
  return null;
}

var url = `https://api.telegram.org/bot${botToken}/sendMessage`;

msg.url = url;
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = JSON.stringify({
  chat_id: chatId,
  text: msg.telegram_text,
  parse_mode: 'Markdown'
});

return msg;

var a = msg.alert;
msg.topic = `INSERT INTO price_alerts (symbol, alert_type, price, threshold, message, sent_at)
  VALUES ('${a.symbol}', '${a.alert_type}', ${a.price}, ${a.threshold}, '${msg.telegram_text.replace(/'/g,"''")}', NOW())`;
return msg;

var symbols = ['BTCUSDT', 'ETHUSDT', 'SOLUSDT'];
var out = symbols.map(s => {
  var p = flow.get('price_' + s);
  return p ? `${s}: $${p.price}` : `${s}: waiting...`;
}).join(' | ');
node.warn(out);
return null;

var limit = parseInt(msg.req.query.limit || 20);
msg.topic = `SELECT id, symbol, alert_type, price, threshold, message, sent_at
FROM price_alerts
ORDER BY sent_at DESC
LIMIT ${limit}`;
return msg;
